-- Schema-only snapshot for isolated PostgreSQL tests. No production rows or credentials.
create role anon; create role authenticated; create role service_role;
create schema auth; create schema reservation_private; create schema net; create schema cron;
create table auth.users(id uuid primary key,email text);
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create sequence public.reservation_audit_id_seq;
create table public.reservation_audit (id bigint generated by default as identity not null,reservation_id uuid not null,previous_status text,new_status text not null,actor uuid,created_at timestamp with time zone default now() not null,telegram_actor_id bigint,telegram_actor_name text,telegram_action text);
alter table public.reservation_audit add PRIMARY KEY (id);
create table public.reservation_games (id uuid default gen_random_uuid() not null,title text not null,starts_at timestamp with time zone not null,capacity integer default 9 not null,is_open boolean default true not null,table_no text default ''::text not null,description text default ''::text not null,created_at timestamp with time zone default now() not null,session_id uuid,schedule_kind text default 'manual'::text not null,game_no text default ''::text not null,booking_state text default 'open'::text not null,is_default_queue boolean default false not null);
alter table public.reservation_games add CHECK ((booking_state = ANY (ARRAY['open'::text, 'closed'::text])));
alter table public.reservation_games add CHECK (((capacity >= 1) AND (capacity <= 30)));
alter table public.reservation_games add PRIMARY KEY (id);
create unique index reservation_single_default_queue on public.reservation_games(is_default_queue) where is_default_queue;
alter table public.reservation_games add CHECK ((schedule_kind = ANY (ARRAY['manual'::text, 'live'::text])));
create table public.reservations (id uuid default gen_random_uuid() not null,game_id uuid not null,player_name text not null,arrival_at timestamp with time zone not null,lookup_token uuid default gen_random_uuid() not null,status text default 'pending'::text not null,note text default ''::text not null,created_at timestamp with time zone default now() not null,updated_at timestamp with time zone default now() not null,reviewed_by uuid,reviewed_at timestamp with time zone,member_number text,member_user_id uuid,guest_note text default ''::text not null,telegram_notification_claimed_at timestamp with time zone,telegram_notified_at timestamp with time zone,version integer default 0 not null,player_name_en text,player_name_ko text,contact_required boolean default false not null);
alter table public.reservations add CHECK (((player_name_en IS NULL) OR ((length(player_name_en) >= 2) AND (length(player_name_en) <= 80))));
alter table public.reservations add CHECK (((player_name_ko IS NULL) OR ((length(player_name_ko) >= 2) AND (length(player_name_ko) <= 80))));
alter table public.reservations add UNIQUE (lookup_token);
alter table public.reservations add PRIMARY KEY (id);
alter table public.reservations add CHECK (((char_length(player_name) >= 2) AND (char_length(player_name) <= 80)));
alter table public.reservations add CHECK ((status = ANY (ARRAY['pending'::text, 'confirmed'::text, 'waitlisted'::text, 'rejected'::text, 'cancelled'::text, 'checked_in'::text, 'no_show'::text])));
create table public.user_profiles (user_id uuid not null,email text,display_name text,role text default 'pending'::text not null,agency_id uuid,active boolean default true not null,created_at timestamp with time zone default now() not null,updated_at timestamp with time zone default now() not null,username text);
alter table public.user_profiles add PRIMARY KEY (user_id);
alter table public.user_profiles add CHECK ((role = ANY (ARRAY['admin'::text, 'staff'::text, 'agent'::text, 'pending'::text, 'desk'::text, 'cashier'::text])));
create table reservation_private.outbox(id uuid primary key default gen_random_uuid(),reservation_id uuid,version integer,payload jsonb,chat_id text,message_id bigint,state text default 'queued',created_at timestamptz default now());
create function reservation_private.dispatch() returns integer language sql as $$select 0$$;
create table cron.job(jobname text,schedule text,command text);
create function cron.schedule(text,text,text) returns bigint language plpgsql as $$begin insert into cron.job values($1,$2,$3); return 1; end$$;
create function net.http_post(url text,headers jsonb,body jsonb,timeout_milliseconds integer) returns bigint language sql as $$select 1::bigint$$;
create publication supabase_realtime;
create function public.reservation_telegram_target() returns text language sql as $$select '-1'::text$$;
CREATE OR REPLACE FUNCTION public.current_app_role()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((select role from public.user_profiles where user_id=auth.uid() and active=true),'pending');
$function$;

CREATE OR REPLACE FUNCTION public.cancel_poker_reservation(p_token uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare rid uuid; old text;
begin
 select id,status into rid,old from public.reservations where lookup_token=p_token for update;
 if rid is null or old not in ('pending','confirmed','waitlisted') then return false; end if;
 update public.reservations set status='cancelled',updated_at=now() where id=rid;
 insert into public.reservation_audit(reservation_id,previous_status,new_status) values(rid,old,'cancelled');
 return true;
end $function$;

CREATE OR REPLACE FUNCTION public.review_poker_reservation(p_id uuid, p_status text, p_expected_version integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.reservations%rowtype; g public.reservation_games%rowtype; gid uuid;
begin
 if coalesce(public.current_app_role(),'') not in ('admin','staff','desk','cashier') then raise exception 'Staff access required'; end if;
 if p_expected_version is null then raise exception 'Refresh reservation before processing'; end if;
 select game_id into gid from public.reservations where id=p_id;
 select * into g from public.reservation_games where id=gid for update;
 select * into r from public.reservations where id=p_id for update;
 if r.id is null then raise exception 'Reservation not found'; end if;
 if r.game_id<>gid or r.version<>p_expected_version then raise exception 'Another staff member updated this reservation. Refresh and try again.'; end if;
 if r.status=p_status and not r.contact_required then return true; end if;
 if not ((r.status in ('pending','waitlisted') and p_status in ('confirmed','waitlisted','rejected','cancelled')) or (r.status='confirmed' and p_status in ('waitlisted','checked_in','no_show','cancelled')) or (r.status='confirmed' and p_status='confirmed' and r.contact_required)) then raise exception 'This status change is not allowed'; end if;
 if p_status in ('confirmed','checked_in') and (select count(*) from public.reservations where game_id=gid and id<>p_id and status in ('confirmed','checked_in'))>=g.capacity then raise exception 'No seats available. Use the waitlist.'; end if;
 update public.reservations set status=p_status,contact_required=false,reviewed_by=auth.uid(),reviewed_at=now() where id=p_id;
 insert into public.reservation_audit(reservation_id,previous_status,new_status,actor) values(p_id,r.status,p_status,auth.uid());
 return true;
end $function$;

CREATE OR REPLACE FUNCTION public.assign_poker_reservation(p_id uuid, p_game uuid, p_expected_version integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.reservations%rowtype; g public.reservation_games%rowtype; gid uuid;
begin
 if public.current_app_role() not in ('admin','staff','desk','cashier') then raise exception 'Staff access required'; end if;
 select game_id into gid from public.reservations where id=p_id;
 -- All operations that take a game and booking lock use this ordering.
 perform id from public.reservation_games where id in (gid,p_game) order by id for update;
 select * into r from public.reservations where id=p_id for update;
 if r.id is null then raise exception 'Reservation not found'; end if;
 if p_expected_version is null or r.version<>p_expected_version or r.game_id<>gid then raise exception 'Reservation changed. Refresh and try again.'; end if;
 if r.status not in ('pending','waitlisted','confirmed') then raise exception 'This reservation cannot be reassigned'; end if;
 if gid=p_game then return true; end if;
 select * into g from public.reservation_games where id=p_game and is_open;
 if g.id is null then raise exception 'Target game is closed'; end if;
 if g.is_default_queue then raise exception 'Assign a scheduled game, not the intake queue'; end if;
 if exists(select 1 from public.reservations where game_id=p_game and id<>p_id and lower(player_name)=lower(r.player_name) and status in ('pending','confirmed','waitlisted','checked_in')) then raise exception 'Player already has a reservation for this game'; end if;
 if r.status='confirmed' and (select count(*) from public.reservations where game_id=p_game and status in ('confirmed','checked_in'))>=g.capacity then raise exception 'Target game is full'; end if;
 update public.reservations set game_id=p_game,reviewed_by=auth.uid(),reviewed_at=now() where id=p_id;
 insert into public.reservation_audit(reservation_id,previous_status,new_status,actor) values(p_id,r.status,r.status,auth.uid());
 return true;
end $function$;

CREATE OR REPLACE FUNCTION reservation_private.booking_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
 if new.status is distinct from old.status then new.contact_required:=false; end if;
 if (new.status,new.game_id,new.arrival_at,new.guest_note,new.player_name,new.player_name_en,new.player_name_ko,new.contact_required)
 is distinct from (old.status,old.game_id,old.arrival_at,old.guest_note,old.player_name,old.player_name_en,old.player_name_ko,old.contact_required) then
  new.version:=old.version+1; new.updated_at:=now();
 else new.version:=old.version; end if;
 return new;
end $function$;

CREATE OR REPLACE FUNCTION reservation_private.enqueue_booking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare g public.reservation_games%rowtype;
begin
 if tg_op='UPDATE' then if new.version=old.version then return new; end if; end if;
 select * into g from public.reservation_games where id=new.game_id;
 insert into reservation_private.outbox(reservation_id,version,payload) values(new.id,new.version,
 jsonb_build_object('reservation_id',new.id,'version',new.version,'event',case when tg_op='INSERT' then 'requested' else 'updated' end,
 'status',new.status,'contact_required',new.contact_required,'player_name',new.player_name,'player_name_en',new.player_name_en,'player_name_ko',new.player_name_ko,
 'arrival_at',new.arrival_at,'guest_note',new.guest_note,'game_title',g.title,'table_no',g.table_no,'game_no',g.game_no));
 begin perform reservation_private.dispatch(); exception when others then null; end;
 return new;
end $function$;

CREATE OR REPLACE FUNCTION public.apply_reservation_telegram_action(p_delivery uuid, p_chat text, p_message bigint, p_action text, p_actor bigint, p_actor_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.reservations%rowtype; g public.reservation_games%rowtype; gid uuid; rid uuid; next_status text;
begin
 if p_action is null or p_action not in ('confirm','contact','cancel') or p_actor is null or p_actor<=0 then raise exception 'Invalid staff action'; end if;
 select reservation_id into rid from reservation_private.outbox where id=p_delivery;
 select game_id into gid from public.reservations where id=rid;
 -- Same lock order as web staff review, assignment and booking creation.
 select * into g from public.reservation_games where id=gid for update;
 select * into r from public.reservations where id=rid for update;
 if r.id is null or r.game_id<>gid or not public.reservation_telegram_action_context(p_delivery,p_chat,p_message) then
  return jsonb_build_object('result','stale');
 end if;
 if r.status not in ('pending','waitlisted','confirmed') then return jsonb_build_object('result','inactive'); end if;
 -- Explicit cancel prevents a replayed CONFIRM callback from cancelling a reservation.
 if p_action='cancel' and r.status<>'confirmed' then return jsonb_build_object('result','inactive'); end if;
 if (p_action='confirm' and r.status='confirmed' and not r.contact_required) or (p_action='contact' and r.contact_required) then return jsonb_build_object('result','unchanged'); end if;
 if p_action='confirm' then
  if not g.is_open then return jsonb_build_object('result','closed'); end if;
  if (select count(*) from public.reservations where game_id=gid and id<>r.id and status in ('confirmed','checked_in'))>=g.capacity then return jsonb_build_object('result','full'); end if;
 end if;
 next_status:=case when p_action='confirm' then 'confirmed' when p_action='cancel' then 'cancelled' else r.status end;
 update public.reservations set status=next_status,contact_required=(p_action='contact'),reviewed_by=null,reviewed_at=now() where id=r.id;
 insert into public.reservation_audit(reservation_id,previous_status,new_status,telegram_actor_id,telegram_actor_name,telegram_action)
 values(r.id,r.status,next_status,p_actor,left(p_actor_name,100),p_action);
 return jsonb_build_object('result',case when p_action='confirm' then 'confirmed' when p_action='cancel' then 'cancelled' else 'contact' end);
end $function$;

CREATE OR REPLACE FUNCTION public.reservation_public_stats()
 RETURNS TABLE(game_id uuid, confirmed_count bigint, pending_count bigint, waiting_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
 select g.id,
 (select count(*) from public.reservations r where r.game_id=g.id and r.status in ('confirmed','checked_in')),
 (select count(*) from public.reservations r where r.game_id=g.id and r.status='pending'),
 (select count(*) from public.reservations r where r.game_id=g.id and r.status='waitlisted')
 from public.reservation_games g where g.is_open and (g.is_default_queue or g.starts_at>now()-interval '12 hours');
$function$;

CREATE OR REPLACE FUNCTION public.reservation_telegram_action_context(p_delivery uuid, p_chat text, p_message bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
 select exists(select 1 from reservation_private.outbox o join public.reservations r on r.id=o.reservation_id
 where o.id=p_delivery and o.state='sent' and o.chat_id=p_chat and o.message_id=p_message
 and o.version=r.version and p_chat=public.reservation_telegram_target());
$function$;

alter table public.reservation_games enable row level security;
create policy "reservation games public read" on public.reservation_games for select to anon,authenticated using(true);
create trigger reservation_version before update on public.reservations for each row execute function reservation_private.booking_version();
create trigger reservation_outbox after insert or update on public.reservations for each row execute function reservation_private.enqueue_booking();
